package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class StatementSignsTest {
 @Test public void uniqueSignForEveryPublicConditionAndFiniteFreshSupply(){Generator generator=new Generator(new Random(121));List<String> recent=new ArrayList<>();Set<String> signs=new HashSet<>();Set<Integer> holes=new HashSet<>();CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",StatementSigns.ID,1);for(int i=0;i<1344;i++){Question q=generator.next(StatementSigns.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=StatementSigns.read(q);assertNotNull(v);holes.add(v[4]);String expected=v[4]==0?(v[3]==0?"+":"−"):"=";signs.add(expected);q.answers=new String[]{"poison"};int correct=0;for(String sign:List.of("+","−","="))if(new Checker().check(q,List.of(),List.of(sign)).correct())correct++;assertEquals(1,correct);assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());assertEquals(Set.of("+","−","="),new HashSet<>(q.choices));HelpPlan plan=HelpPlan.forQuestion(q);assertEquals(3,plan.size());assertFalse(plan.canTransfer());for(int j=0;j<3;j++){assertTrue(plan.step(j).accepts(""+v[j]));assertFalse(plan.step(j).before.matches(".*\\d.*"));}}assertEquals(Set.of("+","−","="),signs);assertEquals(Set.of(0,1,2),holes);assertEquals(recent.get(0),generator.next(StatementSigns.ID,recent,false,limits).signature());}
 @Test public void zeroAndReversedEqualityAndInvalidPublicStatements(){for(int[] args:new int[][]{{0,0,20,0},{1,20,20,0},{0,0,0,1},{1,0,0,2}}){Question q=StatementSigns.make(args[0],args[1],args[2],args[3]);assertNotNull(StatementSigns.read(q));}try{StatementSigns.make(0,2,0,0);fail("ambiguous zero operand");}catch(IllegalArgumentException expected){}Question q=StatementSigns.make(0,2,3,1);q.prompt=StatementSigns.PROMPT+"\n2 + 3 □ 7";assertNull(StatementSigns.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("=")).status);Learning.Profile profile=new Learning.Profile();GlobalCurriculum.chooseCountry(profile,"GB");GlobalCurriculum.choosePack(profile,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(profile).inGrade(StatementSigns.ID,1));assertFalse(GlobalCurriculum.pack(profile).inGrade(StatementSigns.ID,2));}
}
